using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (string? status, string? search, IShipmentService svc) =>
            Results.Ok(await svc.GetShipmentsAsync(status, search)));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
        {
            var dto = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
            return dto is null ? Results.NotFound() : Results.Ok(dto);
        }).AllowAnonymous();

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, IShipmentService svc) =>
            Results.Ok(await svc.UpdateShipmentStatusAsync(id, newStatus)));
    }
}

