@page "/"

<PageTitle>ShipmentTracker — Home</PageTitle>

<div class="text-center py-5">
    <h1 class="display-4">📦 ShipmentTracker</h1>
    <p class="lead mt-3">Real-time logistics tracking for dispatchers and customers.</p>

    <div class="row justify-content-center mt-4 g-4">
        <div class="col-md-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">🔍 Track a Shipment</h5>
                    <p class="card-text">Enter your tracking number to check status and estimated delivery.</p>
                    <div class="input-group">
                        <input type="text" class="form-control" placeholder="e.g. TRK-100001"
                               @bind="trackingInput" @bind:event="oninput"
                               @onkeydown="HandleTrackKeyDown" />
                        <button class="btn btn-primary" @onclick="GoToTrack">Track</button>
                    </div>
                </div>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">📋 Dispatcher Dashboard</h5>
                    <p class="card-text">View and manage all shipments with status filters.</p>
                    <a href="shipments" class="btn btn-outline-primary">Open Dashboard</a>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private NavigationManager Nav { get; set; } = default!;

    private string trackingInput = string.Empty;

    private void GoToTrack()
    {
        if (!string.IsNullOrWhiteSpace(trackingInput))
            Nav.NavigateTo($"track/{Uri.EscapeDataString(trackingInput.Trim())}");
    }

    private void HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            GoToTrack();
    }
}

